commands.stdout:
# /usr/lib/systemd/system/prometheus-node-exporter.service
[Unit]
Description=Prometheus exporter for machine metrics
Documentation=https://github.com/prometheus/node_exporter

[Service]
Restart=on-failure
User=prometheus
EnvironmentFile=/etc/default/prometheus-node-exporter
ExecStart=/usr/bin/prometheus-node-exporter $ARGS
ExecReload=/bin/kill -HUP $MAINPID
TimeoutStopSec=20s
SendSIGKILL=no

[Install]
WantedBy=multi-user.target

/etc/default/prometheus-node-exporter:
# Set the command-line arguments to pass to the server.
# Due to shell escaping, to pass backslashes for regexes, you need to double
# them (\\d for \d). If running under systemd, you need to double them again
# (\\\\d to mean \d), and escape newlines too.
ARGS=""

/etc/nftables.conf:
#!/usr/sbin/nft -f

flush ruleset

table inet filter {
	chain input {
		type filter hook input priority filter;
	}
	chain forward {
		type filter hook forward priority filter;
	}
	chain output {
		type filter hook output priority filter;
	}
}

active/listener:
active
inactive
State  Recv-Q Send-Q Local Address:Port Peer Address:PortProcess
LISTEN 0      4096               *:9100            *:*    users:(("prometheus-node",pid=2097,fd=3))

commands.command:
sudo -n tee /etc/nftables.conf >/dev/null <<'ANTRIEB_NFT_EOF'
#!/usr/sbin/nft -f

flush ruleset

table inet node_exporter_filter {
    chain input {
        type filter hook input priority filter; policy accept;
        ip saddr 10.100.22.10 tcp dport 9100 accept
        tcp dport 9100 reject with tcp reset
    }
}
ANTRIEB_NFT_EOF
sudo -n nft -c -f /etc/nftables.conf
sudo -n systemctl enable --now nftables
sudo -n nft list table inet node_exporter_filter

